import{_ as a,o as r,c as i,j as t,a as s,a5 as o}from"./chunks/framework.BF53ZjCA.js";const y=JSON.parse(`{"title":"Find a Gemstone's Coordinates","description":"Build a first map of gemstone classification through materials, structure, optical phenomena, and color causes.","frontmatter":{"title":"Find a Gemstone's Coordinates","description":"Build a first map of gemstone classification through materials, structure, optical phenomena, and color causes."},"headers":[],"relativePath":"classification/intro.md","filePath":"classification/intro.md","lastUpdated":1789241305000}`),n={name:"classification/intro.md"};function d(l,e,c,m,h,p){return r(),i("div",null,[...e[0]||(e[0]=[t("h1",{id:"find-a-gemstone-s-coordinates",tabindex:"-1"},[s("Find a Gemstone's Coordinates "),t("a",{class:"header-anchor",href:"#find-a-gemstone-s-coordinates","aria-label":`Permalink to "Find a Gemstone's Coordinates"`},"​")],-1),t("blockquote",null,[t("p",null,"From materials and structure to optical phenomena, a first map of the gemstone world.")],-1),t("p",null,"Classification is not a label placed on a stone. It answers four questions: what it is, how it formed, how it presents light, and where to look next.",-1),t("div",{class:"classification-map",role:"list","aria-label":"Four ways to observe a gemstone"},[t("a",{class:"classification-map__item",href:"./mineral-groups/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"01"),t("strong",null,"Material"),t("span",null,"What it is")]),t("a",{class:"classification-map__item",href:"./crystal-systems/cubic",role:"listitem"},[t("span",{class:"classification-map__index"},"02"),t("strong",null,"Structure"),t("span",null,"How it is arranged")]),t("a",{class:"classification-map__item",href:"./optical-phenomena/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"03"),t("strong",null,"Optics"),t("span",null,"How it shows light")]),t("a",{class:"classification-map__item",href:"./color-causes/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"04"),t("strong",null,"Color"),t("span",null,"Why it is colored")])],-1),o('<h2 id="_01-·-what-is-it-materials-and-origins" tabindex="-1">01 · What is it? Materials and origins <a class="header-anchor" href="#_01-·-what-is-it-materials-and-origins" aria-label="Permalink to &quot;01 · What is it? Materials and origins&quot;">​</a></h2><p>Many natural gemstones are minerals, but gem materials are not limited to minerals. GemAtlas first separates materials by origin and properties, then relates them to crystal structure, optical phenomena, and color causes.</p><table tabindex="0"><thead><tr><th>Material category</th><th>What to ask</th><th>Representative materials</th></tr></thead><tbody><tr><td>Natural minerals</td><td>Naturally formed with a defined composition and crystal structure</td><td>Corundum, beryl, quartz, diamond</td></tr><tr><td>Mineraloids / amorphous materials</td><td>Gem materials without a complete long-range crystal structure</td><td>Opal, obsidian</td></tr><tr><td>Organic materials</td><td>Formed through biological activity or biogenic processes</td><td>Pearl, amber, coral</td></tr><tr><td>Synthetic materials</td><td>Made in a laboratory and comparable to a natural counterpart</td><td>Synthetic ruby, synthetic emerald, CVD diamond</td></tr><tr><td>Simulants</td><td>Another material used to imitate a target gem&#39;s appearance</td><td>Cubic zirconia, glass, moissanite</td></tr></tbody></table><h3 id="representative-mineral-families" tabindex="-1">Representative mineral families <a class="header-anchor" href="#representative-mineral-families" aria-label="Permalink to &quot;Representative mineral families&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mineral family</th><th>Representative gems</th></tr></thead><tbody><tr><td>Corundum</td><td>Ruby, sapphire</td></tr><tr><td>Beryl</td><td>Emerald, aquamarine, morganite</td></tr><tr><td>Quartz</td><td>Amethyst, citrine, rock crystal</td></tr><tr><td>Garnet</td><td>Tsavorite, demantoid, almandine</td></tr><tr><td>Tourmaline</td><td>Paraíba, watermelon tourmaline</td></tr><tr><td>Spinel</td><td>Red and blue spinel</td></tr><tr><td>Diamond</td><td>Colourless diamond, fancy-colour diamond</td></tr><tr><td>Feldspar</td><td>Moonstone, labradorite, amazonite</td></tr><tr><td>Zoisite</td><td>Tanzanite</td></tr><tr><td>Opal</td><td>Precious opal, fire opal</td></tr></tbody></table><blockquote><p>“Precious” and “semi-precious” are traditional commercial terms, not strict modern gemological categories. Value is better discussed through rarity, beauty, durability, treatment, and market demand.</p></blockquote><h2 id="_02-·-how-is-it-arranged-crystal-systems-and-structure" tabindex="-1">02 · How is it arranged? Crystal systems and structure <a class="header-anchor" href="#_02-·-how-is-it-arranged-crystal-systems-and-structure" aria-label="Permalink to &quot;02 · How is it arranged? Crystal systems and structure&quot;">​</a></h2><p>Crystal structure describes the ordered arrangement of atoms or ions in space. Gemology commonly uses seven crystal systems to describe crystal symmetry. Opal, obsidian, and amber need a separate treatment as amorphous or mineraloid materials.</p><table tabindex="0"><thead><tr><th>Crystal system</th><th>Representative gems</th><th>Observation cue</th></tr></thead><tbody><tr><td>Cubic / isometric</td><td>Diamond, spinel, garnet</td><td>Three equal axes with high symmetry</td></tr><tr><td>Tetragonal</td><td>Zircon, rutile</td><td>Two equal axes and a distinct third axis</td></tr><tr><td>Orthorhombic</td><td>Tanzanite, chrysoberyl, topaz</td><td>Three unequal, mutually perpendicular axes</td></tr><tr><td>Hexagonal</td><td>Beryl, apatite</td><td>A sixfold symmetry axis is characteristic</td></tr><tr><td>Trigonal</td><td>Ruby, sapphire, quartz, tourmaline</td><td>Threefold symmetry is a key feature</td></tr><tr><td>Monoclinic</td><td>Orthoclase, spodumene</td><td>Axes are not all at right angles</td></tr><tr><td>Triclinic</td><td>Kyanite, turquoise</td><td>The lowest symmetry; axes are unequal and oblique</td></tr><tr><td>Amorphous / mineraloid</td><td>Opal, obsidian, amber</td><td>No complete long-range crystal order</td></tr></tbody></table><p><em>Begin with the <a href="./crystal-systems/cubic.html">cubic system</a>, then compare how symmetry relates to gem properties.</em></p><h2 id="_03-·-how-does-it-show-light-optical-phenomena" tabindex="-1">03 · How does it show light? Optical phenomena <a class="header-anchor" href="#_03-·-how-does-it-show-light-optical-phenomena" aria-label="Permalink to &quot;03 · How does it show light? Optical phenomena&quot;">​</a></h2><p>Optical phenomena are an important observational entry point, but a visible effect, its cause, and its trade name should not be treated as the same thing. GemAtlas records the appearance separately from the structures or inclusions that produce it.</p><table tabindex="0"><thead><tr><th>Phenomenon</th><th>Visible expression</th><th>Representative materials</th></tr></thead><tbody><tr><td>Asterism</td><td>Intersecting rays form a star</td><td>Star ruby, star sapphire</td></tr><tr><td>Chatoyancy</td><td>A movable band of light appears</td><td>Cat&#39;s-eye chrysoberyl, tiger&#39;s eye</td></tr><tr><td>Color change</td><td>Color shifts under different light sources</td><td>Alexandrite, color-change sapphire</td></tr><tr><td>Play of color</td><td>Angle-dependent spectral flashes</td><td>Opal</td></tr><tr><td>Iridescence</td><td>Thin or layered structures produce interference colors</td><td>Labradorite and related materials</td></tr><tr><td>Adularescence</td><td>A soft blue-white floating glow</td><td>Moonstone</td></tr><tr><td>Aventurescence</td><td>Plate-like inclusions create sparkle</td><td>Aventurine, sunstone</td></tr></tbody></table><p><em>Enter <a href="./optical-phenomena/intro.html">Optical Phenomena</a> for causes, observation methods, and identification notes.</em></p><h2 id="_04-·-why-is-it-colored-causes-of-color" tabindex="-1">04 · Why is it colored? Causes of color <a class="header-anchor" href="#_04-·-why-is-it-colored-causes-of-color" aria-label="Permalink to &quot;04 · Why is it colored? Causes of color&quot;">​</a></h2><p>Color is not an isolated surface label. It is the result of light interacting with matter. Three important mechanisms are:</p><table tabindex="0"><thead><tr><th>Mechanism</th><th>Core question</th><th>Representative direction</th></tr></thead><tbody><tr><td>Transition-metal ions</td><td>Which wavelengths are selectively absorbed by ions in the lattice?</td><td>Chromium, iron, manganese, cobalt, copper</td></tr><tr><td>Color centers</td><td>How do lattice defects change light absorption?</td><td>Vacancies, interstitials, irradiation-related defects</td></tr><tr><td>Charge transfer</td><td>How do electrons move between neighboring ions or energy levels?</td><td>Metal–metal and oxygen–metal transfer</td></tr></tbody></table><p>Color grouping is useful for observation and search, but it cannot replace identification. A proper color description also considers hue, tone, saturation, lighting, and viewing direction.</p><p><em>See <a href="./color-causes/intro.html">Color Causes</a> to connect visible color with physical and chemical mechanisms.</em></p><h2 id="_05-·-from-coordinates-to-the-gemstone-index" tabindex="-1">05 · From coordinates to the Gemstone Index <a class="header-anchor" href="#_05-·-from-coordinates-to-the-gemstone-index" aria-label="Permalink to &quot;05 · From coordinates to the Gemstone Index&quot;">​</a></h2><p>A single gemstone can occupy several coordinates. Opal, for example, is an amorphous or mineraloid material and may display play of color. Sapphire belongs to the corundum family and has trigonal symmetry. Classification is not one box; it is a multidimensional index.</p><p>Every GemAtlas entry has its own page with physical properties, optical characteristics, treatments, and references. Continue through <a href="./mineral-groups/intro.html">Mineral Groups</a>, <a href="./crystal-systems/cubic.html">Crystal Systems</a>, or <a href="./optical-phenomena/intro.html">Optical Phenomena</a>. When you are ready to browse the complete collection, open the <a href="./../gems/">Gemstone Index</a>.</p><div class="classification-index-cta"><span class="classification-index-cta__count">60</span><div><strong>Gemstone Index · The Stone Index</strong><p>All 60 species in one searchable learning entry — from name and mineral family to the full reference page.</p></div><a href="../gems/">Browse the collection ↗</a></div>',23)])])}const f=a(n,[["render",d]]);export{y as __pageData,f as default};
